import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Siswa> kelas = new ArrayList<>();
        kelas.add(new Siswa("Citra", 88));
        kelas.add(new Siswa("Andi", 75));
        kelas.add(new Siswa("Budi", 92));

        Collections.sort(kelas);
        System.out.println(kelas);

        Collections.sort(kelas, new Comparator<Siswa>() {
            @Override
            public int compare(Siswa a, Siswa b) {
                return Integer.compare(b.getNilai(), a.getNilai());
            }
        });
        System.out.println(kelas);
    }
}

class Siswa implements Comparable<Siswa> {
    private String nama;
    private int nilai;

    Siswa(String nama, int nilai) {
        this.nama = nama;
        this.nilai = nilai;
    }

    String getNama() {
        return nama;
    }

    int getNilai() {
        return nilai;
    }

    @Override
    public int compareTo(Siswa lain) {
        return nama.compareTo(lain.nama);
    }

    @Override
    public String toString() {
        return nama + "(" + nilai + ")";
    }
}

