import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Produk> toko = new ArrayList<>();
        toko.add(new Produk("Buku", 5000));
        toko.add(new Produk("Tas", 150000));
        toko.add(new Produk("Pensil", 2000));
        Collections.sort(toko, new Comparator<Produk>() {
            @Override
            public int compare(Produk a, Produk b) {
                return Integer.compare(a.getHarga(), b.getHarga());
            }
        });
        System.out.println(toko);
        System.out.println(toko.get(0).getNama());
    }
}

class Produk {
    private String nama;
    private int harga;

    Produk(String nama, int harga) {
        this.nama = nama;
        this.harga = harga;
    }

    String getNama() {
        return nama;
    }

    int getHarga() {
        return harga;
    }

    @Override
    public String toString() {
        return nama + " " + harga;
    }
}

